# -*- coding: utf-8 -*-
import json
N=[
("Ouverture internationale","Ensemble des liens d’une économie avec le reste du monde : échanges de biens et services, circulation des facteurs de production et mouvements de capitaux."),
("Ouverture commerciale","Échanges de biens et de services entre les résidents d’un pays et le reste du monde ; dimension strictement commerciale de la mondialisation."),
("Ouverture productive","Circulation internationale des facteurs de production, notamment le capital productif et le travail."),
("Ouverture financière","Circulation internationale des capitaux financiers, placements et titres, distincte de l’investissement productif."),
("Ouverture monétaire","Dimension liée aux mouvements de devises qui accompagnent les échanges et les placements internationaux."),
("Commerce international","Échanges internationaux de biens et de services entre résidents et non-résidents."),
("Exportation","Vente par un résident d’un bien ou d’un service à un non-résident."),
("Importation","Achat par un résident d’un bien ou d’un service auprès d’un non-résident."),
("IDE","Investissement direct à l’étranger : investissement réalisé dans un autre pays dans une logique productive et de contrôle durable."),
("Investissement de portefeuille","Achat d’actifs financiers étrangers dans une logique de placement, sans prise de contrôle de l’entreprise."),
("Capital productif","Capital investi dans des moyens de production, par opposition au capital purement financier."),
("Capital financier","Capital placé en titres et actifs financiers, mobile et liquide."),
("Marché des changes","Marché sur lequel s’échangent les devises, passage obligé de la plupart des opérations internationales."),
("Devise","Monnaie étrangère utilisée dans les transactions internationales."),
("Bon du Trésor","Titre de dette publique ; son achat par un non-résident illustre l’articulation entre ouverture financière et ouverture monétaire."),
("Mondialisation","Processus d’interdépendance et d’intégration croissantes des économies, qui dépasse le seul commerce international."),
("Interdépendance","Situation dans laquelle les économies dépendent mutuellement les unes des autres."),
("Intégration","Processus par lequel les économies nationales s’articulent en un ensemble de plus en plus unifié."),
("Charles-Albert Michalet","Économiste montrant que la mondialisation est un processus multidimensionnel, irréductible au commerce international."),
("Configuration internationale","Première configuration de Michalet : la mondialisation y passe essentiellement par les échanges commerciaux entre nations."),
("Configuration multinationale","Deuxième configuration de Michalet : les firmes s’implantent à l’étranger et l’investissement direct devient central."),
("Configuration globale","Troisième configuration de Michalet : la production est fragmentée et les marchés financiers s’unifient à l’échelle mondiale."),
("Hypermondialisation","Cumul des trois dimensions — commerciale, productive et financière — aboutissant à une ouverture quantitativement sans précédent."),
("Pierre-Noël Giraud","Économiste analysant les globalisations comme une généralisation des compétitions entre territoires."),
("Compétition des territoires","Mise en concurrence des espaces nationaux pour attirer capitaux, activités et emplois."),
("Privilège exorbitant","Avantage conféré aux États-Unis par le statut international du dollar : attirer durablement les capitaux et financer leurs déséquilibres à bas coût."),
("BRICS","Brésil, Russie, Inde, Chine, Afrique du Sud : grands émergents dont la montée traduit un rééquilibrage de l’économie mondiale."),
("Rattrapage","Processus par lequel une économie moins avancée comble son écart de développement avec les pays les plus riches."),
("Divergence","Écartement des trajectoires économiques, notamment entre pays en développement inégalement insérés dans la mondialisation."),
("Arsenalisation","Usage de la politique économique — sanctions, contrôles des exportations, droits de douane — comme instrument de rapport de force."),
("Centre / périphérie","Grille de lecture opposant des économies industrialisées dominantes à des économies spécialisées dans les produits primaires."),
("Raúl Prebisch","Économiste montrant que la spécialisation primaire enferme les périphéries dans une détérioration des termes de l’échange."),
("Termes de l’échange","Rapport entre le prix des exportations et celui des importations ; leur détérioration oblige à exporter davantage pour importer autant."),
("DIT traditionnelle","Division internationale du travail fondée sur une spécialisation verticale : matières premières au Sud, industrie au Nord."),
("Échange inégal","Théorie selon laquelle le commerce mondial repose sur des rapports de domination et transfère de la valeur des périphéries vers le centre."),
("Acemoglu et Robinson","Auteurs analysant le rôle des institutions extractives dans le blocage du développement."),
("Institutions extractives","Institutions organisées au profit d’une minorité, qui découragent l’investissement et entravent le développement."),
("Économie du développement","Branche de l’analyse économique née de l’étude des blocages spécifiques aux pays en développement."),
("Malédiction des ressources","Paradoxe selon lequel l’abondance de matières premières peut freiner la diversification et le développement au lieu de les favoriser."),
("FMN","Firme multinationale : entreprise implantée dans plusieurs pays, d’abord en quête de ressources et de marchés."),
("Firme globale","Firme organisant sa production à l’échelle mondiale en fragmentant ses activités selon les avantages de chaque territoire."),
("DIPP","Décomposition internationale des processus productifs : fragmentation de la chaîne de valeur entre plusieurs territoires."),
("Chaîne de valeur mondiale","Fragmentation des étapes de production entre plusieurs pays, chacune localisée là où les conditions sont les plus favorables."),
("Stratégie offensive","Politique d’insertion active dans la mondialisation, visant la montée en gamme et la conquête de positions, comme celle de la Chine."),
("Stratégie défensive","Politique visant à protéger l’appareil productif et les positions acquises face à la concurrence internationale."),
("Ménage consommateur","Généralement gagnant de la mondialisation par l’accès à des biens plus variés et moins chers."),
("Ménage travailleur","Gagnant ou perdant selon l’exposition de son secteur et de sa qualification à la concurrence internationale."),
("Ménage épargnant","Susceptible de bénéficier de la globalisation financière par la diversification de ses placements."),
("Branko Milanovic","Économiste des inégalités mondiales, auteur de la courbe de l’éléphant."),
("Courbe de l’éléphant","Représentation des gains de revenu par percentile mondial entre 1988 et 2008, montrant un double mouvement d’inégalités."),
("Big bang des inégalités","Divergence brutale, à partir de la révolution industrielle, entre pays industrialisés et économies restées à l’écart."),
("Inégalités entre pays","Écarts de revenu entre nations, réduits par le rattrapage des grands émergents."),
("Inégalités internes","Écarts de revenu à l’intérieur d’un pays, que la mondialisation peut au contraire renforcer."),
("Balance des paiements","Document comptable enregistrant l’ensemble des opérations entre les résidents d’un pays et le reste du monde."),
("Compte courant","Composante de la balance des paiements regroupant les échanges de biens, de services, les revenus et les transferts courants."),
("Solde commercial","Différence entre les exportations et les importations de biens ; il ne se confond pas avec le solde courant."),
("Solde courant","Solde du compte courant, plus large que le solde commercial car il intègre services, revenus et transferts."),
("Compte financier","Composante enregistrant les mouvements de capitaux entre résidents et non-résidents."),
("Compte de capital","Compte intermédiaire enregistrant certains transferts en capital et acquisitions d’actifs non financiers."),
("Équilibre comptable","Principe selon lequel la balance des paiements est équilibrée par construction : tout déficit courant a une contrepartie financière."),
("Identité macroéconomique","Relation X − M = (S − I) + (T − G) reliant le solde extérieur à l’épargne privée et au solde public."),
("Épargne","Partie du revenu non consommée ; son écart à l’investissement détermine en partie le solde extérieur."),
("Déficit jumeaux","Situation où un déficit public s’accompagne d’un déficit extérieur, illustrée par les États-Unis sous Reagan."),
("Déficit extérieur","Solde courant négatif ; il traduit un besoin de financement vis-à-vis du reste du monde, sans être nécessairement un problème."),
("Excédent extérieur","Solde courant positif ; il traduit une capacité de financement, mais peut signaler une demande intérieure insuffisante."),
("Besoin de financement","Situation d’une économie dont l’investissement excède l’épargne disponible, ce qui appelle des capitaux extérieurs."),
("Capacité de financement","Situation inverse : l’épargne excède l’investissement et l’économie prête au reste du monde."),
("Déséquilibres mondiaux","Persistance de larges excédents et déficits courants entre grandes zones, source d’instabilité financière internationale."),
("Taux d’ouverture","Indicateur traditionnel mesurant le poids du commerce extérieur dans le PIB, calculé à partir des exportations et des importations."),
("Taux d’exportation","Rapport des exportations au PIB, exprimé en pourcentage."),
("Commerce en valeur ajoutée","Mesure corrigeant le double comptage des échanges de biens intermédiaires dans les chaînes de valeur mondiales."),
("Double comptage","Biais des statistiques traditionnelles : un bien franchissant plusieurs fois les frontières est compté à chaque passage."),
("Biens intermédiaires","Produits incorporés dans une production ultérieure ; leur circulation gonfle les statistiques commerciales brutes."),
("Contenu en importations des exportations","Part des intrants étrangers dans ce qu’un pays exporte ; il mesure son insertion dans les chaînes de valeur."),
("Dépendance","Situation d’un pays tributaire de l’étranger pour un intrant, un débouché ou une technologie critique."),
("Vulnérabilité","Exposition d’une économie aux ruptures d’approvisionnement le long des chaînes de valeur mondiales."),
("Relocalisation","Rapatriement d’activités productives précédemment délocalisées, motivé par la sécurité des approvisionnements."),
("Première mondialisation","Phase d’intégration internationale allant du XIXᵉ siècle à 1914, portée par la révolution industrielle et les transports."),
("Révolution des transports","Chemin de fer, navire à vapeur et canaux, qui abaissent les coûts et rendent possible l’essor des flux internationaux."),
("Étalon-or","Régime monétaire international de la première mondialisation, garantissant la convertibilité et la stabilité des changes."),
("Migrations de la première mondialisation","Mouvements de population massifs, notamment européens vers les Amériques, caractéristiques de l’avant-1914."),
("Première mondialisation financière","Circulation massive de capitaux avant 1914, souvent dirigée du centre européen vers les économies neuves."),
("Entre-deux-guerres","Période de repli marquée par le protectionnisme, l’effondrement des flux et le basculement de la puissance vers les États-Unis."),
("Protectionnisme","Politique de restriction des importations par droits de douane, quotas ou normes."),
("Droits de douane","Taxes sur les importations, instrument central du protectionnisme."),
("Remondialisation","Réouverture progressive des économies après 1945, appuyée sur de nouvelles institutions internationales."),
("Nouvelle géographie des échanges","Déplacement du centre de gravité du commerce mondial vers l’Asie émergente."),
("Mondialisation contemporaine","Phase moins migratoire que la première mondialisation, mais beaucoup plus financière et productive."),
("Slowbalization","Ralentissement de la progression de l’ouverture après 2008, sans recul massif des flux."),
("Démondialisation","Recul effectif de l’intégration internationale ; le ralentissement observé depuis 2008 ne suffit pas à l’attester."),
("Fragmentation","Recomposition des échanges en blocs régionaux ou affinitaires plutôt que repli généralisé."),
("Régionalisation","Concentration croissante des échanges à l’intérieur de zones géographiques proches."),
("Crise de 2008","Point d’inflexion à partir duquel la progression du commerce mondial ralentit durablement."),
("Spécialisation","Concentration d’une économie sur certaines productions ; elle crée des gains mais aussi des différences de trajectoire."),
("Gains à l’échange","Bénéfices tirés du commerce international, inégalement répartis entre pays et entre groupes sociaux."),
("Avantage comparatif","Spécialisation selon les coûts relatifs ; celui de la Chine fondé sur le faible coût du travail s’érode avec sa montée en gamme."),
("Montée en gamme","Déplacement d’une économie vers des productions à plus forte valeur ajoutée."),
("Délocalisation","Transfert d’une activité productive vers un territoire offrant de meilleures conditions de coût ou d’accès au marché."),
("Attractivité","Capacité d’un territoire à attirer capitaux, activités et compétences dans la compétition internationale."),
("Leadership économique","Position dominante dans l’économie mondiale, passée de l’Europe aux États-Unis puis contestée par l’Asie émergente."),
("Rivalité Chine / États-Unis","Compétition économique et technologique structurant la mondialisation contemporaine."),
("Souveraineté économique","Capacité d’un État à maîtriser ses approvisionnements, ses technologies et ses choix de politique économique."),
("Décrochage européen","Recul relatif du poids de l’Union européenne dans le PIB mondial et dans les parts de marché."),
("Parts de marché","Poids d’un pays dans les exportations mondiales ; indicateur de compétitivité."),
("Résidents / non-résidents","Distinction comptable fondant la balance des paiements et la mesure des échanges extérieurs."),
("Transferts courants","Opérations sans contrepartie — aide, envois de fonds des migrants — enregistrées au compte courant."),
("Revenus primaires","Revenus du travail et du capital échangés avec le reste du monde, composante du compte courant."),
("Flux de capitaux","Mouvements internationaux de fonds, plus volatils que les échanges de biens et sensibles aux conditions financières."),
("Interdépendance financière","Imbrication des systèmes financiers nationaux, qui propage rapidement les chocs d’un pays à l’autre."),
]
out=[{"term":t,"def":d,"type":"definition"} for t,d in N]
json.dump(out, open('ch21_notions.json','w'), ensure_ascii=False, indent=0)
assert len({n['term'].lower() for n in out})==len(out), "doublon"
print("notions:",len(out),"— aucun doublon")
